insert into instructors (id, name, role, short_bio, bio, qualifications, specialties, years, photo_path, sort_order) values ('rossi', 'Marco Rossi', 'Direttore tecnico · Maestro nazionale', 'Guida la scuola tennis e la squadra agonistica dell''ASD.', array['Marco insegna tennis da oltre vent''anni e dirige l''area tecnica del circolo. Ha costruito la scuola tennis giovanile e segue la squadra che partecipa ai campionati federali.', 'Nei corsi per bambini e ragazzi lavora su coordinazione e divertimento prima che sulla tecnica. Con gli agonisti prepara il programma stagionale di allenamento e tornei.'], array['Maestro nazionale FITP', 'Preparatore atletico di primo livello', 'Corso di aggiornamento sul tennis giovanile'], array['Mini tennis e scuola junior', 'Preparazione agonistica', 'Lezioni private'], 22, null, 0);
insert into instructors (id, name, role, short_bio, bio, qualifications, specialties, years, photo_path, sort_order) values ('bianchi', 'Elena Bianchi', 'Istruttrice di secondo grado', 'Segue i corsi per adulti, dai principianti ai giocatori di club.', array['Elena ha iniziato a insegnare dopo una carriera nei campionati a squadre. Nei corsi per adulti punta su pochi concetti chiari, ripetuti in situazioni di gioco reali.', 'Ama lavorare con chi riparte dopo una pausa e vuole tornare a giocare con costanza e senza infortuni.'], array['Istruttrice di secondo grado FITP', 'Giocatrice di serie D1'], array['Tennis adulti base e intermedio', 'Tattica di doppio', 'Ripartenza dopo una pausa'], 12, null, 1);
insert into instructors (id, name, role, short_bio, bio, qualifications, specialties, years, photo_path, sort_order) values ('verdi', 'Luca Verdi', 'Istruttore di padel', 'Responsabile del padel: corsi, clinic e tornei di coppia.', array['Luca ha portato il padel nel circolo nel 2019 e oggi coordina corsi, clinic e il torneo sociale. Prima giocava a tennis a livello agonistico.', 'Nelle lezioni insiste su posizione in campo e uso delle pareti, gli aspetti che fanno la differenza nelle prime partite in doppio.'], array['Istruttore di padel FIT', 'Arbitro di padel'], array['Padel base e intermedio', 'Clinic tecnici', 'Organizzazione tornei'], 8, null, 2);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('mini', 'tennis', 'Mini tennis', 'Principianti', '5–8 anni', 5, 8, 'Mar e Gio', '16:30–17:30', 8, 'Max 6 allievi', 'Maestro Rossi', 'rossi', '5 ottobre 2026', 55, 'Il primo contatto con racchetta e palla attraverso giochi di coordinazione, con palline morbide e campo ridotto.', 0);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('junior', 'tennis', 'Scuola tennis Junior', 'Base e intermedio', '9–14 anni', 9, 14, 'Lun e Mer', '17:30–19:00', 8, 'Max 6 allievi', 'Maestro Rossi', 'rossi', '5 ottobre 2026', 70, 'Fondamentali, primi punti giocati e partecipazione ai tornei giovanili del circolo.', 1);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('adulti-base', 'tennis', 'Tennis adulti base', 'Principianti', 'Da 15 anni', 15, 99, 'Mar e Gio', '20:00–21:00', 8, 'Max 4 allievi', 'Maestra Bianchi', 'bianchi', '6 ottobre 2026', 80, 'Dritto, rovescio, servizio e regole del gioco per chi inizia o riparte dopo una lunga pausa.', 2);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('adulti-inter', 'tennis', 'Tennis adulti intermedio', 'Intermedio', 'Da 15 anni', 15, 99, 'Lun e Mer', '20:00–21:00', 8, 'Max 4 allievi', 'Maestra Bianchi', 'bianchi', '5 ottobre 2026', 90, 'Tattica, gioco a rete e match play per migliorare la costanza in partita.', 3);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('padel-base', 'padel', 'Padel base', 'Principianti', 'Da 14 anni', 14, 99, 'Ven', '19:00–20:30', 4, 'Max 4 allievi', 'Maestro Verdi', 'verdi', '9 ottobre 2026', 60, 'Posizione in campo, colpi di base, uso delle pareti e le prime partite in doppio.', 4);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('padel-inter', 'padel', 'Padel intermedio', 'Intermedio', 'Da 14 anni', 14, 99, 'Sab', '10:00–11:30', 4, 'Max 4 allievi', 'Maestro Verdi', 'verdi', '10 ottobre 2026', 70, 'Bandeja, vibora, uscite di parete e costruzione del punto in coppia.', 5);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('agonistica', 'tennis', 'Preparazione agonistica', 'Agonisti', 'Da 10 anni', 10, 99, 'Lun, Mer e Ven', '18:00–20:00', 12, 'Max 6 allievi', 'Maestro Rossi', 'rossi', '5 ottobre 2026', 140, 'Allenamento tecnico e atletico per chi gioca i campionati federali con la squadra dell''ASD.', 6);
insert into courses (id, sport, name, level, age_label, age_min, age_max, days, time_label, lessons, group_size, coach, instructor_id, starts_on, price, description, sort_order) values ('privata', 'tennis', 'Lezione privata', 'Tutti i livelli', 'Tutte le età', 0, 99, 'Su appuntamento', 'Orario da concordare', 1, '1 o 2 allievi', 'A scelta', null, 'Tutto l''anno', 40, 'Una lezione di un''ora costruita sui tuoi obiettivi, nel tennis o nel padel.', 7);
insert into events (id, event_date, starts_at, category, title, summary, description, place, price_label, signup_info, poster_path) values ('torneo-padel', '2026-10-24', '09:00', 'Padel', 'Torneo sociale di padel', 'Coppie libere, formula a gironi e finale nel tardo pomeriggio. Aperitivo per tutti.', array['Una giornata di padel aperta a soci e non soci. Le coppie si formano liberamente e giocano in gironi da quattro, con finale in serata.', 'Al termine, aperitivo e premiazioni in club house. Sono previsti premi per le prime tre coppie e per la coppia più simpatica.'], 'Campi Padel A e B', '€ 20 a coppia', 'Iscrizione in segreteria entro il 21 ottobre. Posti limitati a 16 coppie.', null);
insert into events (id, event_date, starts_at, category, title, summary, description, place, price_label, signup_info, poster_path) values ('open-autunno', '2026-11-07', '08:30', 'Tennis', 'Open d''autunno singolare', 'Torneo aperto a tesserati e non, categorie 4.1–4.6. Montepremi in materiale tecnico.', array['Torneo di singolare a tabellone con consolazione, aperto a giocatori tesserati FITP e non tesserati (con certificato medico).', 'Le partite si giocano al meglio dei due set con tie-break decisivo. Il calendario viene pubblicato in segreteria il giorno prima.'], 'Campi 1, 2 e 3', '€ 25 a giocatore', 'Iscrizione online o in segreteria entro il 4 novembre.', null);
insert into events (id, event_date, starts_at, category, title, summary, description, place, price_label, signup_info, poster_path) values ('cena-sociale', '2026-11-21', '20:30', 'Sociale', 'Cena sociale dell''ASD', 'Serata con premiazioni della stagione e presentazione dei corsi invernali.', array['La cena di fine stagione per soci, famiglie e allievi dei corsi. Premiazione dei tornei sociali e presentazione del programma invernale.', 'Menu fisso con opzioni vegetariane. Segnala eventuali allergie al momento dell''iscrizione.'], 'Club house', '€ 28 a persona, bambini under 12 € 15', 'Prenotazione obbligatoria in segreteria entro il 16 novembre.', null);
insert into events (id, event_date, starts_at, category, title, summary, description, place, price_label, signup_info, poster_path) values ('giornata-scuola', '2026-12-12', '10:00', 'Tennis', 'Giornata della scuola tennis', 'Mini-tornei per bambini dai 5 ai 12 anni, con gli istruttori della società.', array['Una mattina di mini-tornei e giochi per bambini dai 5 ai 12 anni, seguiti dagli istruttori della scuola tennis.', 'Gli accompagnatori possono assistere dai bordi campo. Al termine, merenda per tutti i partecipanti.'], 'Campi 1, 2 e 3', 'Ingresso libero', 'Non serve iscriversi. Per i nuovi allievi è prevista una lezione di prova gratuita.', null);
insert into events (id, event_date, starts_at, category, title, summary, description, place, price_label, signup_info, poster_path) values ('clinic-padel', '2027-01-09', '15:00', 'Padel', 'Clinic di padel con il maestro', 'Due ore di tecnica su bandeja, vibora e uscite di parete per giocatori di livello intermedio.', array['Due ore di lavoro tecnico con il maestro Verdi su bandeja, vibora e uscite di parete, con esercizi a gruppi di quattro.', 'Adatto a chi ha già qualche mese di gioco alle spalle. Palline fornite dal circolo.'], 'Padel B (coperto)', '€ 30 a persona', 'Iscrizione in segreteria. Massimo 8 partecipanti.', null);
